package dev.workshopvideo.core;
import static dev.workshopvideo.core.CoreChecks.*;
final class DesktopBehaviorChecks {
 static void run(){
  check(DesktopPages.automatic(1080,2400,1080,2400,1)==1,"portrait image is one natural screen");check(DesktopPages.automatic(3840,2160,1080,2400,1)==4,"landscape splits into four portrait-sized segments");check(DesktopPages.automatic(1920,1080,1080,2400,1)==4,"page count derives from aspect ratio rather than pixel resolution");check(DesktopPages.resolve(false,9,5,3840,2160,1080,2400,1)==5,"real launcher count overrides aspect estimate");check(DesktopPages.resolve(true,3,5,3840,2160,1080,2400,1)==3,"explicit user segment count wins over launcher metadata");check(DesktopPages.resolve(true,1,5,3840,2160,1080,2400,1)==1,"user may disable background segmentation with one page");
  LauncherPaging p=new LauncherPaging();p.gestureFallback(true);p.pages(5);p.system(1,-1,100);p.touch(.7f,.5f,0,100);p.touch(.65f,.5f,2,116);check(p.value()>.5f,"same-frame swipe after vendor callback is not blocked for120ms");p.touch(.63f,.5f,2,132);p.touch(.63f,.5f,1,140);check(p.value()==.75f,"short fast launcher fling advances with sufficient distance and speed");
  LauncherPaging manual=new LauncherPaging();manual.gestureFallback(true);manual.pages(3);manual.manual(true);manual.system(1,.25f,0);check(manual.pageCount()==3,"manual pages ignore reported system count");manual.touch(.8f,.5f,0,1000);manual.touch(.3f,.5f,2,1100);manual.touch(.3f,.5f,1,1200);check(manual.value()==1,"manual three-page displacement advances one segment");
  LauncherPaging single=new LauncherPaging();single.pages(1);single.manual(true);single.system(0,.25f,0);single.system(1,.25f,10);check(single.value()==.5f,"single manual page stays centered despite system callbacks");
  PageAnimation a=new PageAnimation();a.target(1,false);float last=a.value();for(int i=0;i<60;i++){float next=a.step(1/60f);check(next>=last&&next<=1,"monotonic no-overshoot page animation "+i);last=next;}check(a.value()==1,"settling reaches exact endpoint");a.target(.25f,true);check(a.value()==.25f,"finger tracking is immediate rather than eased twice");a.target(.75f,false);float at30=0;for(int i=0;i<6;i++)at30=a.step(1/30f);PageAnimation b=new PageAnimation();b.target(.25f,true);b.target(.75f,false);for(int i=0;i<12;i++)b.step(1/60f);check(Math.abs(at30-b.value())<.00001,"animation is frame-rate independent");
  check(PowerPlayback.freeze(true,true),"enabled setting freezes in system power saver");check(!PowerPlayback.freeze(true,false),"user may opt out of power saver freezing");check(!PowerPlayback.freeze(false,true),"leaving power saver restores dynamic state");check(PowerPlayback.play(true,true,false),"cold-start low-power wallpaper must decode first frame");check(!PowerPlayback.play(true,true,true),"static wallpaper pauses decoder once frame exists");check(PowerPlayback.play(true,false,true),"decoder resumes after exiting power saver");check(!PowerPlayback.play(false,false,false),"hidden wallpaper never starts decoder");check(!PowerPlayback.animate(true,true),"static mode stops animation scheduler");
  check(!WallpaperGeometry.canPagePicture(1920,1080,1080,2400,"fill",true,1),"unzoomed fill has no scrolling room");check(WallpaperGeometry.canPagePicture(1920,1080,1080,2400,"free",true,1.5f),"zoomed free alignment exposes horizontal scrolling room");check(WallpaperGeometry.freePosition(1.5f,0,0,true,0)==.5f&&WallpaperGeometry.freePosition(1.5f,0,0,true,1)==-.5f,"free alignment scrolls from left edge to right edge");
  float[] c=PictureColors.matrix(1,0,1,0);check(c[0]==0&&c[3]==.5f&&c[7]==.5f&&c[11]==.5f,"zero contrast gives neutral gray in shared GPU/Canvas matrix");var cover=WallpaperGeometry.picture(1920,1080,1080,2400,"cover",true,0,1,0,0);var end=WallpaperGeometry.picture(1920,1080,1080,2400,"cover",true,1,1,0,0);check(cover.u0()==0&&Math.abs(end.u0()+end.uSize()-1)<.00001,"cover paging spans the full image exactly");var fill=WallpaperGeometry.picture(1920,1080,1080,2400,"fill",true,1,1,0,0);check(fill.scaleX()==1&&fill.scaleY()==1&&fill.uSize()==1&&fill.vSize()==1,"fill displays all pixels stretched");var free=WallpaperGeometry.picture(1920,1080,1080,2400,"free",false,.5f,1,0,0);check(free.scaleX()==1&&free.scaleY()<1&&free.uSize()==1,"free shows whole image with background margins");
 }
}
